     7  #include "config.h"
     8
     9  #include "fu-uf2-firmware.h"
    10  #include "fu-uf2-struct.h"
    11
    12  struct _FuUf2Firmware {
    13          FuFirmware parent_instance;
    14  };
    15
    16  G_DEFINE_TYPE(FuUf2Firmware, fu_uf2_firmware, FU_TYPE_FIRMWARE)
    17
    18  #define FU_UF2_FIRMWARE_BLOCK_FLAG_NONE              0x00000000
    19  #define FU_UF2_FIRMWARE_BLOCK_FLAG_NOFLASH           0x00000001
    20  #define FU_UF2_FIRMWARE_BLOCK_FLAG_IS_CONTAINER      0x00001000
    21  #define FU_UF2_FIRMWARE_BLOCK_FLAG_HAS_FAMILY        0x00002000
    22  #define FU_UF2_FIRMWARE_BLOCK_FLAG_HAS_MD5           0x00004000
    23  #define FU_UF2_FIRMWARE_BLOCK_FLAG_HAS_EXTENSION_TAG 0x00008000
    24
    25  #define FU_U2F_FIRMWARE_TAG_VERSION     0x9fc7bc /* semver of firmware file (UTF-8) */
    26  #define FU_U2F_FIRMWARE_TAG_DESCRIPTION 0x650d9d /* description of device (UTF-8) */
    27  #define FU_U2F_FIRMWARE_TAG_PAGE_SZ     0x0be9f7 /* page size of target device (uint32_t) */
    28  #define FU_U2F_FIRMWARE_TAG_SHA1        0xb46db0 /* SHA-2 checksum of firmware */
    29  #define FU_U2F_FIRMWARE_TAG_DEVICE_ID   0xc8a729 /* device type identifier (uint32_t or uint64_t) */
    30
    31  static gboolean
    32  fu_uf2_firmware_parse_chunk(FuUf2Firmware *self, FuChunk *chk, GByteArray *tmp, GError **error)
    33  {
    34          gsize bufsz = fu_chunk_get_data_sz(chk);
    35          const guint8 *buf = fu_chunk_get_data(chk);
    36          guint32 flags = 0;
    37          guint32 datasz = 0;
    38          g_autoptr(GByteArray) st = NULL;
    39
    40          /* parse */
    41          st = fu_struct_uf2_parse(fu_chunk_get_data(chk),
    42                                   fu_chunk_get_data_sz(chk),
    43                                   0, /* offset */
    44
    45                                   error);
    46          if (st == NULL)
    47                  return FALSE;
    48          flags = fu_struct_uf2_get_flags(st);
    49          if (flags & FU_UF2_FIRMWARE_BLOCK_FLAG_IS_CONTAINER) {
    50                  g_set_error_literal(error,
    51                                      FWUPD_ERROR,
    52                                      FWUPD_ERROR_NOT_SUPPORTED,
    53                                      "container U2F firmware not supported");
    54                  return FALSE;
    55          }
    56          datasz = fu_struct_uf2_get_payload_size(st);
    57          if (datasz > 476) {
    58                  g_set_error(error,
    59                              FWUPD_ERROR,
    60                              FWUPD_ERROR_INVALID_DATA,
    61                              "data size impossible got 0x%08x",
    62                              datasz);
    63                  return FALSE;
    64          }
    65          if (fu_struct_uf2_get_block_no(st) != fu_chunk_get_idx(chk)) {
    66                  g_set_error(error,
    67                              FWUPD_ERROR,
    68                              FWUPD_ERROR_INVALID_DATA,
    69                              "block count invalid, expected 0x%04x and got 0x%04x",
    70                              fu_chunk_get_idx(chk),
    71                              fu_struct_uf2_get_block_no(st));
    72                  return FALSE;
    73          }
    74          if (fu_struct_uf2_get_num_blocks(st) == 0) {
    75                  g_set_error_literal(error,
    76                                      FWUPD_ERROR,
    77                                      FWUPD_ERROR_INVALID_DATA,
    78                                      "block count invalid, expected > 0");
    79                  return FALSE;
    80          }
    81          if (flags & FU_UF2_FIRMWARE_BLOCK_FLAG_HAS_FAMILY) {
    82                  if (fu_struct_uf2_get_family_id(st) == 0) {
    83                          g_set_error_literal(error,
    84                                              FWUPD_ERROR,
    85                                              FWUPD_ERROR_INVALID_DATA,
    86                                              "family_id required but not supplied");
    87                          return FALSE;
    88                  }
    89          }
    90
    91          /* assume first chunk is representative of firmware */
    92          if (fu_chunk_get_idx(chk) == 0) {
    93                  fu_firmware_set_addr(FU_FIRMWARE(self), fu_struct_uf2_get_target_addr(st));
    94                  fu_firmware_set_idx(FU_FIRMWARE(self), fu_struct_uf2_get_family_id(st));
    95          }
    96
    97          /* just append raw data */
    98          g_byte_array_append(tmp, fu_struct_uf2_get_data(st, NULL), datasz);
    99          if (flags & FU_UF2_FIRMWARE_BLOCK_FLAG_HAS_MD5) {
   100                  if (datasz < 24) {
   101                          g_set_error_literal(error,
   102                                              FWUPD_ERROR,
   103                                              FWUPD_ERROR_INVALID_DATA,
   104                                              "not enough space for MD5 checksum");
   105                          return FALSE;
   106                  }
   107          }
   108          if (flags & FU_UF2_FIRMWARE_BLOCK_FLAG_HAS_EXTENSION_TAG) {
   109                  gsize offset = FU_STRUCT_UF2_OFFSET_DATA;
   110                  while (offset < bufsz) {
   111                          guint8 sz = 0;
   112                          guint32 tag = 0;
   113
   114                          /* [SZ][TAG][TAG][TAG][TAG][DATA....] */
   115                          if (!fu_memread_uint8_safe(buf, bufsz, offset, &sz, error))
   116                                  return FALSE;
   117                          if (sz < 4) {
   118                                  g_set_error_literal(error,
   119                                                      FWUPD_ERROR,
   120                                                      FWUPD_ERROR_INVALID_DATA,
   121                                                      "invalid extension tag size");
   122                                  return FALSE;
   123                          }
   124                          if (!fu_memread_uint32_safe(buf,
   125                                                      bufsz,
   126                                                      offset,
   127                                                      &tag,
   128                                                      G_LITTLE_ENDIAN,
   129                                                      error))
   130                                  return FALSE;
   131                          tag &= 0xFFFFFF;
   132                          if (tag == FU_U2F_FIRMWARE_TAG_VERSION) {
   133                                  g_autofree gchar *utf8buf = g_malloc0(sz);
   134                                  if (!fu_memcpy_safe((guint8 *)utf8buf,
   135                                                      sz,
   136                                                      0x0, /* dst */
   137                                                      buf,
   138                                                      bufsz,
   139                                                      offset + 0x4, /* src */
   140                                                      sz - 4,
